## Submitted testbench
```systemverilog
module tb;
  // Clock
  reg clk = 0;
  always #5 clk = ~clk;  // 10ns period (100 MHz) arbitrary

  // DUT signals
  reg rst = 0;
  reg [7:0] s_axis_tdata;
  reg s_axis_tvalid;
  reg [15:0] prescale = 16'd5; // non‑zero prescale
  wire s_axis_tready;
  wire txd;
  wire busy;

  // Instantiate the DUT
  uart_tx #(.DATA_WIDTH(8)) dut (
    .clk(clk),
    .rst(rst),
    .s_axis_tdata(s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .txd(txd),
    .busy(busy),
    .prescale(prescale)
  );

  // Reset generation
  initial begin
    rst = 1'b0;
    #10;
    rst = 1'b1;
    #10;
    rst = 1'b0;
    #10;
  end

  // Main stimulus
  initial begin
    // Wait for reset de‑assertion
    wait (!rst);

    // ----------- First frame (any data) ----------
    s_axis_tdata  = 8'h00;        // arbitrary byte
    s_axis_tvalid = 1'b1;         // raise tvalid
    @(posedge clk);               // hold for one clock
    s_axis_tvalid = 1'b0;         // de‑assert

    // Give the transmitter time to start moving bits (busy will be high)
    // ~50 clock cycles is safely inside the transmission window
    repeat (50) @(posedge clk);

    // ----------- Second frame – data must be 0x3C ----------
    s_axis_tdata  = 8'h3C;        // required data
    // Ensure previous value was 0 (it is, because we just de‑asserted)
    s_axis_tvalid = 1'b1;         // rising edge -> coverage trigger
    @(posedge clk);               // hold one clock so the edge is seen
    s_axis_tvalid = 1'b0;         // de‑assert

    // Wait for the coverage point to be sampled
    repeat (200) @(posedge clk);

    $finish; // clean termination
  end
endmodule
```

